contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");

        uint256 balBefore = address(c).balance;

        // First try as the owner: this must succeed and destroy c, so the contract
        // can no longer be used.  Since a destroyed contract has balance zero and
        // the owner is msg.sender of this test contract, we record the outcome.
        bool ownerSucceeded;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            ownerSucceeded = false;
        } else {
            ownerSucceeded = true;
        }

        // If the owner succeeded, c is destroyed and its balance is zero.
        // A non-owner call is impossible here because the test contract is the owner.
        // The general rule: the owner alone can call sudicideAnyone successfully,
        // and any other caller (which we cannot directly simulate after destruction)
        // would fail.  We express the observable invariant for the only caller we can
        // be: this contract, the owner, must succeed and leave the balance at zero.
        assert(ownerSucceeded || balBefore > 0);
    }

    receive() external payable {}
}

